function createLogger(log) {
    const isAction = !!process.env.GITHUB_ACTIONS;
    const info = (message) => {
        if (isAction) {
            coreExports.info(message);
        }
        else {
            log.info(message);
        }
    };
    const notice = (message) => {
        if (isAction) {
            coreExports.notice(message);
        }
        else {
            log.info(message);
        }
    };
    const warn = (message) => {
        if (isAction) {
            coreExports.warning(message);
        }
        else {
            log.warn(message);
        }
    };
    // GitHub does not support nested `::group::` sections, so callers must not nest `group()` calls.
    const group = (title, render) => {
        if (!isAction) {
            info(`— ${title} —`);
            render();
            return;
        }
        coreExports.startGroup(title);
        try {
            render();
        }
        finally {
            coreExports.endGroup();
        }
    };
    const keyValue = (rows) => {
        info(formatKeyValue(rows));
    };
    const list = (items) => {
        items.forEach(info);
    };
    return { group, info, notice, warn, keyValue, list };
}

const createCollapsibleScreenshot = ([{ entryName }, link], initialOpen = true, imageAttrs = []) => `
<details ${initialOpen ? 'open' : ''}>
    <summary><strong>${entryName}</strong></summary>
    <img src="${link}" ${imageAttrs.join(' ')}/>
</details>
`;
const createReport = (header, screenshotsInfo, { allOpen = true, description = '', imageAttrs = [], }) => `
<h1>${header}</h1>

${description}

${screenshotsInfo
    .map((screenshot) => createCollapsibleScreenshot(screenshot, allOpen, imageAttrs))
    .join('')}
`;
const getFailureReport = (failedTests, newTests, { commitSha, botConfigs }) => `
${failedTests.length
    ? createReport('Failed tests :x:', failedTests, {
        allOpen: true,
        description: botConfigs['failed-report-description'],
        imageAttrs: botConfigs['img-attrs'],
    })
    : ''}
<br />
${newTests.length
    ? createReport('New tests :test_tube:', newTests, {
        allOpen: false,
        imageAttrs: botConfigs['img-attrs'],
    })
    : ''}

<sub>(updated for commit ${commitSha})</sub>
`;

